public str getName()
{
    return fieldPName(InventDim, InventDimension4);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventDim inventDim;
    while select InventDimension4 from inventDim
        group by InventDimension4
    {
        ret.add(inventDim.InventDimension4);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventDimension4));
    qbr.value(queryValue(_value));
}
